/**
 * @file        build-bravojs-bundle.js
 * @description Flattens wasm/cfitsio-wasm.js + wasm/cfitsio-module.js into
 *              one file wrapped in bravojs's module format
 *              (module.declare), the format DCP's package publisher
 *              expects -- see docs/patching-wasm-libraries-for-dcp.pdf in
 *              the Edequity repo (the same pattern used for duckdbwasm,
 *              sofia2wasm, and fftw3wasm). Local (unpublished)
 *              job.requires() tolerates plain CommonJS because it goes
 *              through a real webpack build at deploy time; publish does
 *              not, so this file is pre-wrapped instead.
 *
 * @usage       node build-bravojs-bundle.js
 *              (run after wasm/build.sh; writes package/cfitsio-wasm.js)
 */
'use strict';

const fs = require('fs');
const path = require('path');

const WASM_DIR = path.join(__dirname, '..');

const moduleSrc = fs.readFileSync(path.join(WASM_DIR, 'cfitsio-module.js'), 'utf8');
let wrapperSrc = fs.readFileSync(path.join(WASM_DIR, 'cfitsio-wasm.js'), 'utf8');

// cfitsio-wasm.js declares createCfitsioModule via a require()-vs-globalThis
// guard (added for raw-browser-tab compatibility -- require() doesn't exist
// there, but does in Node and inside a DCP sandbox). In the bundle,
// createCfitsioModule is supplied as a closure parameter instead -- drop
// that whole declaration (and only that declaration; leave everything else,
// including the docblock, untouched for provenance).
const requireLineRegex = /const createCfitsioModule = \(typeof require === 'function'\)\s*\n\s*\? require\('\.\/cfitsio-module'\)\s*\n\s*: globalThis\.CfitsioModule;\n\n/;
if (!requireLineRegex.test(wrapperSrc)) {
  throw new Error("expected to find the createCfitsioModule require()-vs-globalThis guard in cfitsio-wasm.js");
}
wrapperSrc = wrapperSrc.replace(requireLineRegex, '');

const bundle = `/**
 * @file        cfitsio-wasm.js (published bundle)
 * @description Published-package form of wasm/cfitsio-wasm.js + wasm/cfitsio-module.js,
 *              flattened into one file and wrapped in bravojs's module format
 *              (module.declare), per the DCP package publishing convention --
 *              see docs/patching-wasm-libraries-for-dcp.pdf in the Edequity
 *              repo (the same pattern used for duckdbwasm, sofia2wasm, and
 *              fftw3wasm). Generated by build-bravojs-bundle.js; do not
 *              hand-edit -- edit wasm/cfitsio-wasm.js or rerun wasm/build.sh
 *              + this script instead.
 *
 *              Local (unpublished) job.requires() tolerates plain CommonJS
 *              because it goes through a real webpack build at deploy time;
 *              publish does not, so this file is pre-wrapped instead.
 *
 * @usage       job.requires(['cfitsio4wasm/cfitsio-wasm.js']);
 *              // inside the work function:
 *              const cfitsio = require('cfitsio-wasm.js');  // bare filename, no ./
 *              const { naxes, data } = await cfitsio.readImageDouble(fitsBytes);
 *              const fitsBytes = await cfitsio.writeImageDouble(naxes, data);
 */
module.declare([], function (require, exports, module) {
  // ---- cfitsio-module.js (Emscripten build of cfitsio + zlib), verbatim ----
  var createCfitsioModule = (function () {
    var module = { exports: {} };
    var exports = module.exports;
${moduleSrc}
    return module.exports;
  })();

  // ---- cfitsio-wasm.js, with require('./cfitsio-module') replaced by the ----
  // ---- createCfitsioModule captured above ----
  var bundleExports = (function (createCfitsioModule) {
    var module = { exports: {} };
    var exports = module.exports;
${wrapperSrc}
    return module.exports;
  })(createCfitsioModule);

  for (var k in bundleExports) {
    if (Object.prototype.hasOwnProperty.call(bundleExports, k)) exports[k] = bundleExports[k];
  }
});
`;

const outPath = path.join(__dirname, 'cfitsio-wasm.js');
fs.writeFileSync(outPath, bundle);
console.log(`wrote ${outPath} (${bundle.length} bytes)`);
